  function quadOf(x, y){ if (x === 0 && y === 0) return 'origin'; if (y === 0) return 'x-axis'; if (x === 0) return 'y-axis'; return x > 0 ? (y > 0 ? 'Quadrant I' : 'Quadrant IV') : (y > 0 ? 'Quadrant II' : 'Quadrant III'); }
