  // ---- plotting (kind 'plot': the answer is [x, y]) ----
  function PL(q, a, rg, pts, hint, steps, segs){ if (Math.abs(a[0]) > rg || Math.abs(a[1]) > rg) return null; return { q, kind:'plot', a, model:{ type:'grid', range:rg, points:pts || [], segs }, hint, steps }; }
  const H_PL = 'Start at the origin (0, 0). Move left/right for x FIRST, then up/down for y.';
