    ['3', (R, L) => { const y = R.int(-8, 8), x1 = R.int(-9, 3), w = 2 * R.int(1, 4), x2 = x1 + w; const vert = R.chance(0.5); const A = vert ? [y, x1] : [x1, y], B = vert ? [y, x2] : [x2, y], Mi = vert ? [y, x1 + w / 2] : [x1 + w / 2, y];
      return PL(`Plot the point exactly halfway between A ${pr(...A)} and B ${pr(...B)}.`, Mi, 10, [{ x:A[0], y:A[1], label:'A' }, { x:B[0], y:B[1], label:'B' }], 'The segment is straight. Find its length, then go half of it from A.', [`Length: ${w} units. Half: ${w / 2}.`, `From A, go ${w / 2} ${vert ? 'up' : 'right'}: ${pr(...Mi)}`]); }],
    ['123', (R, L) => { const g = rgOf(L), x = R.int(-g, g), y = R.int(-g, g); const xw = x < 0 ? `negative ${-x}` : String(x), yw = y < 0 ? `negative ${-y}` : String(y);
      return PL(`Plot the point where x is ${xw} and y is ${yw}.`, [x, y], g, [], H_PL, plSteps(x, y)); }],
    ['123', (R, L) => { const g = rgOf(L), s = R.int(2, 5), x1 = R.int(-g, g - s), y1 = R.int(-g, g - s); const cs = [[x1, y1], [x1 + s, y1], [x1 + s, y1 + s], [x1, y1 + s]]; const k = R.int(0, 3); const sh = cs.filter((_, i) => i !== k);
      return PL(`Points A, B and C are three corners of a SQUARE. Plot the fourth corner.`, cs[k], g, sh.map((p, i) => ({ x:p[0], y:p[1], label:'ABC'[i] })), 'All four sides of a square are the same length and meet at right angles.', [`The sides are ${s} units long.`, `The missing corner is ${pr(...cs[k])}.`], sh.slice(0, 2).map((p, i) => [p[0], p[1], sh[i + 1][0], sh[i + 1][1]])); }],
    ['123', (R, L) => { const g = rgOf(L), x = R.int(-g, 0), y = R.int(-g, g), d = R.int(2, g); const right = R.chance(0.5); const bx = right ? x + d : x - d; if (Math.abs(bx) > g) return null;
      return PL(`A is at ${pr(x, y)}. Plot point B ${right ? 'to the right of' : 'to the left of'} A so that segment AB is horizontal and ${d} units long.`, [bx, y], g, [{ x, y, label:'A' }], 'Horizontal means B has the same y as A.', [`Same y: ${N(y)}.`, `x: ${N(x)} ${right ? '+' : '−'} ${d} = ${N(bx)}`, `Plot ${pr(bx, y)}.`]); }],
    ['12', (R, L) => { const g = rgOf(L), x = R.int(-g, g), y = R.int(-g, g); const pl = R.pick(PLACES);
      return PL(`On a town grid, the ${pl} is at ${pr(x, y)}. Plot the ${pl}.`, [x, y], g, [], H_PL, plSteps(x, y)); }]
